#include "image_core.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
static unsigned checks;
static size_t peak_bytes;
#define CHECK(v) do{checks++;if(!(v)){fprintf(stderr,"FAIL line %d: %s\n",__LINE__,#v);exit(1);}}while(0)
typedef struct {size_t live,peak,limit,calls;long fail_at;int persistent;} Memory;
typedef union {struct {size_t bytes;} meta;long double align;} Header;
static void*alloc_mem(void*c,size_t n){Memory*m=c;Header*h;size_t call=m->calls++;if((m->fail_at>=0&&(call==(size_t)m->fail_at||(m->persistent&&call>=(size_t)m->fail_at)))||n>m->limit-m->live)return 0;h=malloc(sizeof(*h)+n);if(!h)return 0;h->meta.bytes=n;m->live+=n;if(m->live>m->peak)m->peak=m->live;return h+1;}
static void free_mem(void*c,void*p){Memory*m=c;Header*h;if(!p)return;h=(Header*)p-1;CHECK(h->meta.bytes<=m->live);m->live-=h->meta.bytes;free(h);}
static void memory_init(Memory*m){memset(m,0,sizeof(*m));m->limit=16u*1024u*1024u;m->fail_at=-1;}
static uint64_t digest(const IEDoc*d){uint64_t hash=1469598103934665603ull;int l;size_t i,n=(size_t)d->current.width*d->current.height;hash^=(unsigned)d->current.width;hash*=1099511628211ull;hash^=(unsigned)d->current.height;hash*=1099511628211ull;hash^=(unsigned)d->current.count;hash*=1099511628211ull;hash^=(unsigned)d->current.active;hash*=1099511628211ull;for(l=0;l<d->current.count;l++){hash^=d->current.layers[l].opacity;hash*=1099511628211ull;hash^=d->current.layers[l].visible;hash*=1099511628211ull;for(i=0;i<n;i++){hash^=d->current.layers[l].pixels[i];hash*=1099511628211ull;}}return hash;}
static size_t colored(const IEDoc*d){size_t n=(size_t)d->current.width*d->current.height,i,out=0;for(i=0;i<n;i++)if(d->current.layers[d->current.active].pixels[i]>>24)out++;return out;}
typedef struct {unsigned char*bytes;size_t size,pos,capacity,limit,chunk;int oversize;} Stream;
static size_t stream_write(void*c,const void*p,size_t n){Stream*s=c;size_t take=n;CHECK(n<=4096);if(s->oversize)return n+1;if(s->chunk&&take>s->chunk)take=s->chunk;if(s->limit&&take>s->limit-s->size)take=s->limit-s->size;if(!take)return 0;if(s->size+take>s->capacity){size_t cap=(s->size+take)*2+256;void*q=realloc(s->bytes,cap);CHECK(q!=0);s->bytes=q;s->capacity=cap;}memcpy(s->bytes+s->size,p,take);s->size+=take;return take;}
static size_t stream_read(void*c,void*p,size_t n){Stream*s=c;size_t take=n;CHECK(n<=4096);if(s->oversize)return n+1;if(take>s->size-s->pos)take=s->size-s->pos;if(s->chunk&&take>s->chunk)take=s->chunk;memcpy(p,s->bytes+s->pos,take);s->pos+=take;return take;}
static void setup(IEDoc*d,Memory*m,int w,int h){memory_init(m);CHECK(ie_init(d,alloc_mem,free_mem,m,w,h));}
static void cleanup(IEDoc*d,Memory*m){if(m->peak>peak_bytes)peak_bytes=m->peak;ie_destroy(d);CHECK(m->live==0);}
static void test_brush(void){IEDoc d;Memory m;IEBrush b={IE_RGBA(255,0,0,255),5,100,100,0,0,0};uint64_t hash;setup(&d,&m,24,24);CHECK(ie_new(&d,24,24,0));hash=digest(&d);CHECK(ie_begin(&d));ie_brush(&d,12,12,12,12,&b);CHECK(colored(&d)>10&&colored(&d)<25);CHECK((ie_composite(&d,12,12)&0xffffff)==255);CHECK(ie_undo(&d));CHECK(digest(&d)==hash);CHECK(ie_redo(&d));CHECK(colored(&d)>10);CHECK(ie_begin(&d));b.erase=1;ie_brush(&d,12,12,12,12,&b);CHECK(ie_composite(&d,12,12)==0);CHECK(ie_new(&d,24,24,0));b.erase=0;b.square=1;b.opacity=50;CHECK(ie_begin(&d));ie_brush(&d,12,12,12,12,&b);CHECK(colored(&d)==25);CHECK((ie_composite(&d,12,12)>>24)==127);CHECK(ie_new(&d,24,24,0));b.opacity=100;b.hardness=0;b.square=0;CHECK(ie_begin(&d));ie_brush(&d,12,12,12,12,&b);CHECK((ie_composite(&d,12,12)>>24)>(ie_composite(&d,14,12)>>24));CHECK(ie_new(&d,24,24,0));b.hardness=100;b.diffusion=100;b.size=15;CHECK(ie_begin(&d));ie_brush(&d,12,12,12,12,&b);CHECK(colored(&d)>0&&colored(&d)<150);ie_select(&d,2,3,6,7);CHECK(ie_clear(&d));CHECK(ie_begin(&d));b.diffusion=0;b.size=100;ie_brush(&d,5,5,5,5,&b);CHECK(ie_composite(&d,2,3)>>24);CHECK(!(ie_composite(&d,0,0)>>24));cleanup(&d,&m);}
static void test_shapes_text(void){IEDoc d;Memory m;uint64_t h;setup(&d,&m,80,40);CHECK(ie_new(&d,80,40,0));CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_RECT,2,2,12,12,0xff0000ff,100,1,0,1);CHECK(colored(&d)==40);CHECK(ie_composite(&d,3,3)==0);CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_RECT,20,2,29,11,0xff00ff00,100,1,1,1);CHECK(ie_composite(&d,25,5)==0xff00ff00);CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_ELLIPSE,35,2,45,12,0xffff0000,100,1,0,1);CHECK(ie_composite(&d,40,7)==0);CHECK(ie_composite(&d,40,2)==0xffff0000);CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_LINE,0,25,79,25,0xff00ffff,100,1,0,1);CHECK(ie_composite(&d,60,25)==0xff00ffff);CHECK(ie_new(&d,80,40,0));CHECK(ie_begin(&d));ie_text(&d,0,0,"Cafe",2,0xffffffff,100);h=digest(&d);CHECK(colored(&d)>40);CHECK(ie_new(&d,80,40,0));CHECK(ie_begin(&d));ie_text(&d,0,0,"Caf\xc3\xa9",2,0xffffffff,100);CHECK(digest(&d)!=h);CHECK(ie_glyph_row(0xe9,2)==ie_glyph_row('e',2));CHECK(ie_glyph_row(0xe9,0)!=ie_glyph_row('e',0));CHECK(ie_glyph_row('a',10)==0);CHECK(ie_begin(&d));ie_text(&d,0,20,"\xe0\x80",1,0xff0000ff,100);cleanup(&d,&m);}
static void test_layers_history(void){IEDoc d;Memory m;uint64_t original,changed;uint32_t before[32*24];int i;setup(&d,&m,32,24);original=digest(&d);CHECK(ie_layer_add(&d,"Rouge"));CHECK(d.current.count==2&&d.current.active==1);CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_RECT,4,4,20,20,0xff0000ff,100,1,1,0);CHECK(ie_layer_style(&d,128,1));CHECK((ie_composite(&d,10,10)&255)==255);CHECK(((ie_composite(&d,10,10)>>8)&255)==127);for(i=0;i<32*24;i++)before[i]=ie_composite(&d,i%32,i/32);CHECK(ie_layer_merge_down(&d));CHECK(d.current.count==1);for(i=0;i<32*24;i++)CHECK(before[i]==ie_composite(&d,i%32,i/32));CHECK(ie_undo(&d));CHECK(d.current.count==2);CHECK(ie_layer_duplicate(&d));CHECK(d.current.count==3);CHECK(ie_layer_move(&d,-1));CHECK(d.current.active==1);CHECK(ie_layer_delete(&d));CHECK(d.current.count==2);CHECK(ie_new(&d,32,24,0xffffffff));CHECK(digest(&d)==original);CHECK(ie_begin(&d));ie_text(&d,2,2,"A",1,0xff000000,100);changed=digest(&d);CHECK(original!=changed);CHECK(ie_cancel(&d));CHECK(digest(&d)==original);CHECK(d.redo_count==0);CHECK(ie_begin(&d));ie_text(&d,2,2,"A",1,0xff000000,100);CHECK(ie_undo(&d));CHECK(ie_redo(&d));CHECK(digest(&d)==changed);for(i=0;i<64;i++)CHECK(ie_adjust(&d,1,0,0,100,100,100,0));CHECK(d.undo_count<=IE_MAX_HISTORY&&d.history_bytes<=IE_HISTORY_MAX_BYTES);cleanup(&d,&m);}
static void test_geometry(void){IEDoc d;Memory m;uint64_t h;setup(&d,&m,20,20);CHECK(ie_new(&d,20,20,0));CHECK(ie_begin(&d));ie_shape(&d,IE_SHAPE_RECT,2,2,5,7,0xff0000ff,100,1,1,0);ie_select(&d,2,2,5,7);h=digest(&d);CHECK(ie_translate_selection(&d,5,3));CHECK(ie_composite(&d,2,2)==0&&ie_composite(&d,7,5)==0xff0000ff);CHECK(ie_undo(&d));CHECK(digest(&d)==h);CHECK(ie_transform(&d,100,100,0,0));CHECK(digest(&d)==h);CHECK(ie_undo(&d));CHECK(ie_transform(&d,100,100,0,1));CHECK(colored(&d)==24);CHECK(ie_undo(&d));CHECK(ie_transform(&d,200,100,50,0));CHECK(colored(&d)>24);CHECK(ie_undo(&d));CHECK(ie_resize(&d,40,30));CHECK(d.current.width==40&&d.current.height==30);CHECK(ie_undo(&d));CHECK(digest(&d)==h);CHECK(ie_crop(&d,2,2,4,6));CHECK(d.current.width==4&&d.current.height==6&&colored(&d)==24);CHECK(ie_undo(&d));CHECK(digest(&d)==h);CHECK(!ie_resize(&d,INT_MAX,2));CHECK(digest(&d)==h);CHECK(!ie_crop(&d,0,0,-1,3));CHECK(digest(&d)==h);cleanup(&d,&m);}
static void test_adjust(void){IEDoc d;Memory m;uint64_t before;setup(&d,&m,16,16);CHECK(ie_new(&d,16,16,IE_RGBA(120,80,40,255)));CHECK(ie_adjust(&d,0,0,0,100,100,100,0));CHECK(ie_composite(&d,0,0)==IE_RGBA(120,80,40,255));CHECK(ie_adjust(&d,0,0,-100,100,100,100,0));CHECK((ie_composite(&d,0,0)&255)==((ie_composite(&d,0,0)>>16)&255));CHECK(ie_undo(&d));CHECK(ie_adjust(&d,0,0,0,200,100,50,0));CHECK(ie_composite(&d,0,0)==IE_RGBA(240,80,20,255));CHECK(ie_layer_duplicate(&d));CHECK(ie_layer_style(&d,255,0));before=digest(&d);CHECK(ie_adjust(&d,100,100,100,100,100,100,1));CHECK(d.current.layers[1].pixels[0]==IE_RGBA(240,80,20,255));CHECK(digest(&d)!=before);CHECK(ie_undo(&d));ie_select(&d,2,2,3,3);CHECK(ie_adjust(&d,100,0,0,100,100,100,0));CHECK(d.current.layers[1].pixels[0]==IE_RGBA(240,80,20,255));CHECK(d.current.layers[1].pixels[34]==0xffffffff);cleanup(&d,&m);}
static void test_codecs(void){IEDoc d,e;Memory m,n;Stream project={0},bmp={0};uint64_t h;size_t size,i;setup(&d,&m,37,29);setup(&e,&n,10,10);CHECK(ie_layer_add(&d,"Accent"));CHECK(ie_begin(&d));ie_text(&d,2,2,"Tab5",2,IE_RGBA(10,20,30,190),100);CHECK(ie_layer_style(&d,170,1));h=digest(&d);project.chunk=13;CHECK(ie_save_project(&d,stream_write,&project));CHECK(ie_load_project(&e,stream_read,&project));CHECK(digest(&e)==h);CHECK(e.dirty==0&&e.undo_count==0);project.pos=0;project.bytes[project.size-1]^=1;CHECK(!ie_load_project(&e,stream_read,&project));CHECK(digest(&e)==h);project.bytes[project.size-1]^=1;size=project.size;for(i=0;i<size;i+=211){project.size=i;project.pos=0;CHECK(!ie_load_project(&e,stream_read,&project));CHECK(digest(&e)==h);}project.size=size;project.pos=0;project.oversize=1;CHECK(!ie_load_project(&e,stream_read,&project));project.oversize=0;bmp.chunk=7;CHECK(ie_save_bmp(&d,stream_write,&bmp));CHECK(ie_load_bmp(&e,stream_read,&bmp));CHECK(e.current.width==37&&e.current.height==29&&e.current.count==1);for(i=0;i<37*29;i++)CHECK(ie_composite(&d,(int)(i%37),(int)(i/37))==ie_composite(&e,(int)(i%37),(int)(i/37)));h=digest(&e);size=bmp.size;for(i=0;i<size;i+=127){bmp.size=i;bmp.pos=0;CHECK(!ie_load_bmp(&e,stream_read,&bmp));CHECK(digest(&e)==h);}bmp.size=size;bmp.pos=0;bmp.bytes[28]=16;CHECK(!ie_load_bmp(&e,stream_read,&bmp));CHECK(digest(&e)==h);bmp.bytes[28]=24;{Stream bad={0};bad.limit=80;CHECK(!ie_save_bmp(&d,stream_write,&bad));free(bad.bytes);memset(&bad,0,sizeof(bad));bad.oversize=1;CHECK(!ie_save_project(&d,stream_write,&bad));}free(project.bytes);free(bmp.bytes);cleanup(&d,&m);cleanup(&e,&n);}
static int operation(IEDoc*d,int op){switch(op){case 0:return ie_begin(d);case 1:return ie_layer_add(d,"New");case 2:return ie_layer_duplicate(d);case 3:return ie_clear(d);case 4:return ie_adjust(d,20,10,-30,120,50,100,1);case 5:return ie_resize(d,39,27);case 6:return ie_crop(d,1,1,20,20);case 7:return ie_transform(d,120,80,-50,3);case 8:return ie_translate_selection(d,7,-2);case 9:return ie_layer_delete(d);case 10:return ie_layer_merge_down(d);case 11:return ie_layer_style(d,120,0);case 12:return ie_layer_move(d,-1);default:return ie_new(d,55,30,0);}}
static void test_allocation_failures(void){int op,at,persistent;for(persistent=0;persistent<2;persistent++)for(op=0;op<14;op++)for(at=0;at<12;at++){IEDoc d;Memory m;uint64_t h;int ok;setup(&d,&m,32,24);CHECK(ie_layer_add(&d,"Other"));CHECK(ie_begin(&d));ie_text(&d,1,1,"X",2,0xff00ff00,100);ie_select(&d,1,1,24,20);h=digest(&d);m.fail_at=(long)m.calls+at;m.persistent=persistent;ok=operation(&d,op);if(!ok)CHECK(digest(&d)==h);CHECK(m.live<=m.limit);m.fail_at=-1;cleanup(&d,&m);}}
static void test_memory_bounds(void){IEDoc d;Memory m;int i;setup(&d,&m,1024,1024);CHECK(!ie_layer_add(&d,"Too much"));CHECK(d.current.count==1);CHECK(ie_begin(&d));CHECK(m.peak<16u*1024u*1024u);CHECK(ie_transform(&d,100,100,0,1));for(i=0;i<6;i++)CHECK(ie_adjust(&d,0,0,0,100,100,100,0));CHECK(d.history_bytes<=IE_HISTORY_MAX_BYTES);CHECK(ie_resize(&d,512,512));for(i=0;i<6;i++)CHECK(ie_layer_add(&d,"Layer"));CHECK(d.current.count==7);CHECK(!ie_layer_add(&d,"Limit"));CHECK(ie_begin(&d));CHECK(ie_transform(&d,120,80,25,1));CHECK(m.peak<=m.limit);cleanup(&d,&m);}
static void test_repeated_use(void){IEDoc d;Memory m;int i;setup(&d,&m,64,48);for(i=0;i<400;i++){IEBrush b={IE_RGBA(i%256,100,180,255),i%13+1,70,50,20,0,0};CHECK(ie_begin(&d));ie_brush(&d,i%64,i%48,(i+10)%64,(i+12)%48,&b);if(i%3==0){CHECK(ie_undo(&d));CHECK(ie_redo(&d));}if(i%7==0){CHECK(ie_layer_add(&d,"Transient"));CHECK(ie_layer_delete(&d));}CHECK(d.current.count==1);CHECK(d.history_bytes<=IE_HISTORY_MAX_BYTES);CHECK(d.undo_count<=IE_MAX_HISTORY);CHECK(m.live<m.limit);}cleanup(&d,&m);}
static unsigned yields;
static void yield_count(void*ctx){unsigned*p=ctx;(*p)++;}
static void test_gesture_cancel(void){IEDoc d;Memory m;uint64_t before,after;setup(&d,&m,24,24);ie_set_yield(&d,yield_count,&yields);before=digest(&d);CHECK(ie_begin(&d));ie_text(&d,1,1,"A",1,0xff000000,100);after=digest(&d);CHECK(ie_undo(&d));CHECK(digest(&d)==before&&d.redo_count==1);CHECK(ie_gesture_begin(&d));ie_text(&d,2,2,"B",1,0xff0000ff,100);CHECK(d.saved_redo_count==1&&d.redo_count==0);CHECK(ie_cancel(&d));CHECK(digest(&d)==before&&d.redo_count==1);CHECK(ie_redo(&d));CHECK(digest(&d)==after);CHECK(ie_undo(&d));CHECK(ie_gesture_begin(&d));ie_text(&d,2,2,"B",1,0xff0000ff,100);ie_commit(&d);CHECK(d.saved_redo_count==0&&d.redo_count==0);CHECK(!ie_redo(&d));CHECK(yields>0);cleanup(&d,&m);}
int main(void){test_gesture_cancel();test_brush();test_shapes_text();test_layers_history();test_geometry();test_adjust();test_codecs();test_allocation_failures();test_memory_bounds();test_repeated_use();printf("{\"checks\":%u,\"repeated_cycles\":400,\"allocation_scenarios\":336,\"peak_bytes\":%zu,\"status\":\"passed\"}\n",checks,peak_bytes);return 0;}
